from pathlib import Path
import json,hashlib,datetime
P=Path(__file__).resolve().parent;W=Path('/root/dyq/workspace');O=P/'canonical01'
def read(p):return json.loads(p.read_text()) if p.exists() else None
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def epoch(s):return datetime.datetime.fromisoformat(s).timestamp()
g=read(O/'GUARD_RESULT.json');assert g is not None
c=read(O/'checker.json');m=read(O/'GUARD_METADATA.json');stage=read(O/'STAGE.json');completion=read(O/'COMPLETION.json')
