status='verified_unregistered' if verified else ('blocked_reference_timeout' if g['returncode']==124 and stage and stage['stage']=='reference' and stage['event']=='started' else 'blocked_guard_'+str(g['returncode']) if g['returncode'] in (75,76,78) else 'failed_checker' if c and c.get('status')=='failed' else 'blocked_incomplete_checker')
