result={'worker':'c81d4b0f49f54715','baseline':'ops-nn','operator':'GroupedGemmFwdOp','case_id':'moe-fwd-bfloat16','status':status,'accepted_added':0,'registered':False,'canonical_attempts':1,'guard_returncode':g['returncode'],'checker_returncode':completion['checker_returncode'] if completion else None,'checker_runtime_result':c,'numerical_verdict':'pass' if verified else ('failed' if c and c.get('error_type')=='AssertionError' else None),'last_stage':stage,'verification':c.get('verification') if c else None,'inputs_preserved':c.get('inputs_preserved') if c else None,'candidate_completed':bool((O/'candidate.pt').exists()),'reference_completed':bool((O/'reference.pt').exists()),'timings':{'total_guard_wall_s':g['elapsed_s'],'queue_to_acquire_s':epoch(m['acquired_at'])-epoch(g['requested_at']) if m else None,'idle_check_s':epoch(m['updated_at'])-epoch(m['acquired_at']) if m else None,'child_wall_to_guard_exit_s':epoch(g['finished_at'])-epoch(m['updated_at']) if m else None,'lock_held_to_guard_exit_s':epoch(g['finished_at'])-epoch(m['acquired_at']) if m else None},'source_build_pairs_verified':144,'original_native_source_pins_verified':2163,'adapter_sha256':sha(P/'adapter.py'),'routing':'Private graph.WORKSPACE cache root only; unchanged original adapter/provider/compiler/target/reference/seed/tolerance','reason':'Original full BF16 reference did not return before fixed 300s child deadline; candidate and checker did not complete, no numerical failure verdict.' if status=='blocked_reference_timeout' else status,'evidence':['canonical01/COMMAND.json','canonical01/guard.log','canonical01/GUARD_RESULT.json','canonical01/GUARD_METADATA.json','canonical01/STAGE.json','canonical01/running_maps.txt','PINS.json','POSTCHECK.json','SOURCE_COMPARE.json'],'remaining_issues':[] if verified else ['Canonical validation incomplete; no acceptance or registration. Do not unconditionally rerun or change oracle.'],'finished_at':datetime.datetime.now(datetime.timezone.utc).isoformat()}
(P/'RESULT.json').write_text(json.dumps(result,indent=2)+'\n');(P/'DELIVERY.json').write_text(json.dumps(result,indent=2)+'\n')
files={str(p.relative_to(P)):sha(p) for p in P.rglob('*') if p.is_file() and 'snapshot' not in p.parts and p.name not in ('FILE_HASHES.json','HEARTBEAT.json')}
(P/'FILE_HASHES.json').write_text(json.dumps(files,indent=2)+'\n')
(P/'HEARTBEAT.json').write_text(json.dumps({'phase':'end','status':status,'utc':result['finished_at'],'worker':result['worker'],'accepted_added':0},indent=2)+'\n')
print(json.dumps({k:v for k,v in result.items() if k!='checker_runtime_result'},indent=2))
